import{_ as p,V as c,W as l,X as i,Z as n,a1 as s,$ as a,a0 as u,Y as d,F as e}from"./framework-b1bd8911.js";const r={},g=n("p",null,[s('svg 是矢量图，前端写海报、名片、证书这类"模板型"图非常顺手，改改文字调调样式就能出新图；但业务上我们往往需要的是一张实实在在的 jpg/png 图片（比如保存、分享、发给下游服务）。svg-plugin 做的就是这件事：把 svg 渲染成图片，对上层使用者只暴露一个 '),n("code",null,"SvgRenderWrapper"),s("，一行链式调用搞定。")],-1),k=d(`<p>本篇作为 svg-plugin 的第一篇，先介绍最基础的使用姿势：如何引入依赖、如何把一个 svg 渲染输出为图片，以及输出方式、渲染格式的各种细节。</p><h2 id="_1-问题背景" tabindex="-1"><a class="header-anchor" href="#_1-问题背景" aria-hidden="true">#</a> 1. 问题背景</h2><p>在介绍使用姿势之前，先聊一下这个插件的典型使用场景。</p><p>常见的做法是这样的：设计同学或者我们自己，用 svg 画好一张图的底稿——比如一张带背景图、价格、时间占位的商品海报，或者一张个人名片。svg 本质上就是一段 xml 文本，里面的文字、图片、坐标都是可以程序改写的，这就给了后端一个&quot;程序化出图&quot;的机会：</p><ul><li>把 svg 当作模板，传不同的参数（价格、时间、图片地址），渲染出不同的图片</li><li>一次性把 svg 转成 jpg/png，供后续的业务流程使用</li></ul><p>svg-plugin 内部借助的是 Apache Batik（Java 世界里最主流的 svg 渲染库）来完成 svg -&gt; 位图的转换，并在这个基础上做了模板传参、输出方式封装、缓存提效等增强。本篇聚焦在&quot;渲染输出&quot;这个基本能力上，模板传参请移步下一篇。</p><p>需要提前说明的一点是：svg 渲染涉及字体、透明度、混合模式等一堆细节，实际测试下来这个接口的性能并不算特别出色，但对于常规的使用场景（单次渲染、模板 + 缓存的批量渲染）还是完全 ok 的。</p><h2 id="_2-依赖引入" tabindex="-1"><a class="header-anchor" href="#_2-依赖引入" aria-hidden="true">#</a> 2. 依赖引入</h2><blockquote><p>项目已发布到 maven 中央仓库，因此无需额外操作，直接依赖即可</p></blockquote><p>对于 maven 进行项目管理，可以在 pom.xml 文件中，添加下面的依赖，请注意使用最新的版本</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token comment">&lt;!-- https://mvnrepository.com/artifact/com.github.liuyueyi.media/svg-core --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>dependency</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>com.github.liuyueyi.media<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>svg-core<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>version</span><span class="token punctuation">&gt;</span></span>3.1.0<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>version</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>dependency</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>对于 gradle 进行项目管理，可以在 gradle 文件中，添加下面的依赖</p><div class="language-groovy line-numbers-mode" data-ext="groovy"><pre class="language-groovy"><code><span class="token comment">// https://mvnrepository.com/artifact/com.github.liuyueyi.media/svg-core</span>
implementation <span class="token string">&#39;com.github.liuyueyi.media:svg-core:3.1.0&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>引入 <code>svg-core</code> 之后，batik 相关的依赖（batik-transcoder、batik-anim 等）以及一个 <code>batik-codec-fix</code> 包会自动带入，不需要我们再显示添加，关于 <code>batik-codec-fix</code> 的作用，见后文的说明。</p><h2 id="_3-基本使用姿势" tabindex="-1"><a class="header-anchor" href="#_3-基本使用姿势" aria-hidden="true">#</a> 3. 基本使用姿势</h2><p>直接将 svg 文件渲染为图片，最简的姿势如下：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">testPng</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">BufferedImage</span> img <span class="token operator">=</span> <span class="token class-name">SvgRenderWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token string">&quot;test.svg&quot;</span><span class="token punctuation">)</span>
            <span class="token punctuation">.</span><span class="token function">setType</span><span class="token punctuation">(</span><span class="token class-name">RenderType</span><span class="token punctuation">.</span><span class="token constant">JPG</span><span class="token punctuation">)</span> <span class="token comment">// 默认输出图片为png格式，因此当输出png时，可以省略这个参数设置</span>
            <span class="token punctuation">.</span><span class="token function">asImg</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;---&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>整个过程与 quick-media 系列插件的其他插件一致，都是 <code>of() -&gt; 配置 -&gt; asXxx()</code> 三段式：</p><ul><li><code>SvgRenderWrapper.of(svg)</code>：传入 svg，返回 <code>SvgRenderWrapper.Builder</code> 对象</li><li>中间的链式调用都是配置项：<code>setType()</code> 设置输出图片格式，<code>addParams()</code> 模板传参（下一篇重点介绍），<code>setCacheEnable()</code>/<code>setCacheSize()</code> 缓存设置</li><li><code>asXxx()</code>：触发渲染并输出，输出方式见下一节</li></ul><h3 id="_3-1-of-的传参说明" tabindex="-1"><a class="header-anchor" href="#_3-1-of-的传参说明" aria-hidden="true">#</a> 3.1 of() 的传参说明</h3><p><code>of()</code> 的传参非常的灵活，可以是下面任意一种：</p><ul><li>svg 的文件地址： <ul><li>本地绝对路径，如 <code>d:/quick-media/test.svg</code></li><li>本地相对路径，如 <code>test.svg</code>，相对的是 classpath，适合把模板放在 resources 目录下</li><li>网络地址，如 <code>https://xxx.com/test.svg</code>（http 开头）</li></ul></li><li>svg 的文本内容：以 <code>&lt;svg</code> 开头的一段 svg 字符串，适合模板文件写在代码里、或者从数据库/配置中心读取的场景</li></ul><p>内部判断逻辑很简单，<code>of()</code> 传参如果以 <code>&lt;svg</code> 开头，就当作 svg 正文直接解析；否则当作文件路径处理（http 开头走网络，否则按 classpath 相对路径解析后加载）。</p><h3 id="_3-2-四种输出方式" tabindex="-1"><a class="header-anchor" href="#_3-2-四种输出方式" aria-hidden="true">#</a> 3.2 四种输出方式</h3><p>当前支持四种输出方式，覆盖了绝大多数的使用场景：</p><table><thead><tr><th style="text-align:center;">输出方式</th><th style="text-align:center;">返回值</th><th style="text-align:center;">典型场景</th></tr></thead><tbody><tr><td style="text-align:center;">asImg()</td><td style="text-align:center;">BufferedImage</td><td style="text-align:center;">拿到图片对象，继续在 Java 里处理（如再合成、再加水印）</td></tr><tr><td style="text-align:center;">asStream()</td><td style="text-align:center;">ByteArrayOutputStream</td><td style="text-align:center;">需要 IO 流的场景，如直接写往响应流返回给前端下载</td></tr><tr><td style="text-align:center;">asBytes()</td><td style="text-align:center;">byte[]</td><td style="text-align:center;">需要字节数组的场景，如直接上传 oss、存入数据库</td></tr><tr><td style="text-align:center;">asFile(fileName)</td><td style="text-align:center;">void</td><td style="text-align:center;">直接落盘保存</td></tr></tbody></table><p>另外还有一个隐藏玩法 <code>asSvg()</code>：它不做位图渲染，而是完成模板传参之后，将 svg 的 Document 结构重新序列化为 svg 字符串返回。适合&quot;先在 svg 层面替换参数，再把 svg 文本丢给前端或者另一个渲染流程&quot;的场景。</p><p><strong>asFile 的两个贴心细节</strong>（来自源码 <code>SvgRenderWrapper#autoInitRenderType</code> 与 <code>UriUtil#initFile</code>）：</p><ul><li>输出文件时，会自动根据文件名后缀，来设置渲染图片类型，如 <code>save.jpg</code> 表示将 svg 渲染为 jpg 格式图片（此时可以省略 <code>setType()</code>）</li><li>输出文件时，若指定文件的父目录不存在，会递归的创建父目录，无需担心路径不存在的异常</li></ul><p>比如下面的用法就是完全合法的：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 类型、路径都不用操心，直接写</span>
<span class="token class-name">SvgRenderWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token string">&quot;test.svg&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">asFile</span><span class="token punctuation">(</span><span class="token string">&quot;/tmp/svg/save.jpg&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>如果不带文件后缀，如 <code>asFile(&quot;/tmp/out&quot;)</code>，则会默认按 png 渲染，并自动补上后缀保存为 <code>/tmp/out.png</code>；如果带了不认识的后缀（比如 <code>.gif</code>），则会直接抛 <code>IllegalArgumentException</code>——当前只支持 jpg/png/tiff 三种，明确报错比渲染出一张坏图要友好。</p><h3 id="_3-3-渲染类型-rendertype" tabindex="-1"><a class="header-anchor" href="#_3-3-渲染类型-rendertype" aria-hidden="true">#</a> 3.3 渲染类型 RenderType</h3><p>当前支持将 svg 渲染为 jpg、png、tiff 三种格式图片，对应的枚举是 <code>RenderType</code>：</p><ul><li>png: <code>.setType(RenderType.PNG)</code></li><li>jpg: <code>.setType(RenderType.JPG)</code>（<code>RenderType.JPEG</code> 与之等价，都对应 batik 的 JPEGTranscoder）</li><li>tiff: <code>.setType(RenderType.TIFF)</code></li></ul><p>默认输出的是 png 格式，所以输出 png 时 <code>setType()</code> 可以省略。</p><p>需要注意 png 是无损格式且支持透明，svg 里的透明背景、半透明元素可以原样保留；jpg 不支持透明，透明区域会被填充成实色（通常是白底），如果模板里有大量透明元素，输出 jpg 时视觉上可能会和预期有出入。</p><p><strong>tiff 需要额外依赖</strong></p><p>说明，当希望渲染图片为 tiff 格式时，对于 jdk8 及之下的版本，由于 jdk 本身不支持 tiff 图片，因此需要使用第三方插件来适配，所以请在 pom 中额外添加依赖：</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token comment">&lt;!-- https://mvnrepository.com/artifact/com.twelvemonkeys.imageio/imageio-tiff --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>dependency</span><span class="token punctuation">&gt;</span></span>
  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>groupId</span><span class="token punctuation">&gt;</span></span>com.twelvemonkeys.imageio<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>groupId</span><span class="token punctuation">&gt;</span></span>
  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>artifactId</span><span class="token punctuation">&gt;</span></span>imageio-tiff<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>artifactId</span><span class="token punctuation">&gt;</span></span>
  <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>version</span><span class="token punctuation">&gt;</span></span>3.9.4<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>version</span><span class="token punctuation">&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>dependency</span><span class="token punctuation">&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p>jdk9 及之后的版本自带 tiff 的读写支持，不需要额外加这个依赖。<code>svg-core</code> 内部对该依赖使用的是 provided 范围，即按需引入。</p></blockquote><h2 id="_4-完整示例" tabindex="-1"><a class="header-anchor" href="#_4-完整示例" aria-hidden="true">#</a> 4. 完整示例</h2><p>下面这段 svg 模拟了一张个人名片：左边是图片 + 名字 + 简介，右边是一个公众号推广位，直接复制即可运行：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token annotation punctuation">@Test</span>
<span class="token keyword">public</span> <span class="token keyword">void</span> <span class="token function">testRender</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span>
    <span class="token class-name">String</span> svg <span class="token operator">=</span> <span class="token string">&quot;&lt;svg width=\\&quot;480\\&quot; height=\\&quot;240\\&quot; xmlns=\\&quot;http://www.w3.org/2000/svg\\&quot; xmlns:xlink=\\&quot;http://www.w3.org/1999/xlink\\&quot;&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;    &lt;rect fill=\\&quot;#ffffff\\&quot; style=\\&quot;stroke:#e6e6e6;stroke-width:2\\&quot; id=\\&quot;canvas_background\\&quot; height=\\&quot;100%\\&quot; width=\\&quot;100%\\&quot; y=\\&quot;0\\&quot; x=\\&quot;0\\&quot;/&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;    &lt;svg width=\\&quot;300\\&quot; height=\\&quot;230\\&quot;&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;        &lt;image y=\\&quot;40\\&quot; width=\\&quot;100%\\&quot; height=\\&quot;80\\&quot; text-anchor=\\&quot;middle\\&quot; xlink:href=\\&quot;http://s3.mogucdn.com/mlcdn/c45406/171105_4keid4g9cbh13eeg3l78e6fae325j_640x960.jpg_220x330.jpg\\&quot;/&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;        &lt;text y=\\&quot;150\\&quot; x=\\&quot;50%\\&quot; font-size=\\&quot;18\\&quot; text-anchor=\\&quot;middle\\&quot; style=\\&quot;display: block;\\&quot;&gt;小灰灰Blog&lt;/text&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;        &lt;text y=\\&quot;170\\&quot; x=\\&quot;50%\\&quot; font-size=\\&quot;14\\&quot; text-anchor=\\&quot;middle\\&quot; fill=&#39;#bbb&#39;&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;            &lt;tspan y=\\&quot;180\\&quot; x=\\&quot;50%\\&quot;&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;                码农界新人，Java搬运工一枚\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;            &lt;/tspan&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;            &lt;tspan y=\\&quot;200\\&quot; x=\\&quot;50%\\&quot;&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;                关注不定时分享各种边缘or好用知识点\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;            &lt;/tspan&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;        &lt;/text&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;    &lt;/svg&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;    &lt;line x1=\\&quot;300\\&quot; y1=\\&quot;20\\&quot; x2=\\&quot;270\\&quot; y2=\\&quot;220\\&quot; style=\\&quot;stroke:#e6e6e6;stroke-width:1\\&quot;/&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;    &lt;svg width=\\&quot;170\\&quot; height=\\&quot;230\\&quot; x=\\&quot;300\\&quot;&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;        &lt;image y=\\&quot;30\\&quot; width=\\&quot;100%\\&quot; height=\\&quot;160\\&quot; text-anchor=\\&quot;middle\\&quot; xlink:href=\\&quot;https://static.oschina.net/uploads/img/201707/09205944_0PzS.jpg\\&quot;&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;        &lt;/image&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;        &lt;text y=\\&quot;200\\&quot; x=\\&quot;50%\\&quot; font-size=\\&quot;12\\&quot; text-anchor=\\&quot;middle\\&quot; fill=\\&quot;#999\\&quot;&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;            长按或扫一扫关注\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;        &lt;/text&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;    &lt;/svg&gt;\\n&quot;</span> <span class="token operator">+</span>
            <span class="token string">&quot;&lt;/svg&gt;&quot;</span><span class="token punctuation">;</span>
    <span class="token class-name">SvgRenderWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span>svg<span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">asFile</span><span class="token punctuation">(</span><span class="token string">&quot;/tmp/svg/save.jpg&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
    <span class="token class-name">System</span><span class="token punctuation">.</span>out<span class="token punctuation">.</span><span class="token function">println</span><span class="token punctuation">(</span><span class="token string">&quot;渲染图片完成!&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>渲染输出的图片效果如下：</p><div class="hint-container note"><p class="hint-container-title">效果图</p><p>此处应展示渲染输出的名片效果图，实际输出图可运行上方示例后查看；同款模板的渲染效果可参考官方文档中的名片样图。</p></div><p>再演示一下几种输出方式的切换，同一个 svg，四种姿势拿到结果：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token comment">// 1. 输出文件，根据后缀自动按 jpg 渲染</span>
<span class="token class-name">SvgRenderWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token string">&quot;test.svg&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">asFile</span><span class="token punctuation">(</span><span class="token string">&quot;/tmp/out.jpg&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 2. 输出图片对象，默认 png</span>
<span class="token class-name">BufferedImage</span> img <span class="token operator">=</span> <span class="token class-name">SvgRenderWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token string">&quot;test.svg&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">asImg</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 3. 输出字节</span>
<span class="token keyword">byte</span><span class="token punctuation">[</span><span class="token punctuation">]</span> bytes <span class="token operator">=</span> <span class="token class-name">SvgRenderWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token string">&quot;test.svg&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">setType</span><span class="token punctuation">(</span><span class="token class-name">RenderType</span><span class="token punctuation">.</span><span class="token constant">TIFF</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">asBytes</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 4. 输出流</span>
<span class="token class-name">ByteArrayOutputStream</span> stream <span class="token operator">=</span> <span class="token class-name">SvgRenderWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token string">&quot;test.svg&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">asStream</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>

<span class="token comment">// 5. 模板传参后输出 svg 文本（不做位图渲染）</span>
<span class="token class-name">String</span> newSvg <span class="token operator">=</span> <span class="token class-name">SvgRenderWrapper</span><span class="token punctuation">.</span><span class="token function">of</span><span class="token punctuation">(</span><span class="token string">&quot;test.svg&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">addParams</span><span class="token punctuation">(</span><span class="token string">&quot;svg_2&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;替换文本&quot;</span><span class="token punctuation">)</span><span class="token punctuation">.</span><span class="token function">asSvg</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="_5-batik-codec-fix-是什么" tabindex="-1"><a class="header-anchor" href="#_5-batik-codec-fix-是什么" aria-hidden="true">#</a> 5. batik-codec-fix 是什么</h2><p>如果去翻 svg-plugin 的源码，会发现 plugin 下面有两个模块：<code>batik-codec-fix</code> 与 <code>svg-core</code>。前面的项目是针对 batik 项目的源码做的一些小改造，把 batik 的 png/jpg/tiff 编解码器（codec 包下的 <code>ImageIOPNGImageWriter</code>、<code>PNGRed</code> 那一大坨类）重新打进了一个 jar，通过 SPI 的方式注册进 batik，确保在新的 batik 版本（当前使用 1.16）下 png 图片可以正常输出。</p><p>对于使用者而言，这一层是完全透明的：<code>svg-core</code> 已经依赖了 <code>batik-codec-fix</code>，我们只需要引入 <code>svg-core</code> 一个包，无需关心它的存在；知道它的用途，是为了在排除问题、或者好奇&quot;为什么 batik 官方包渲染 png 会翻车&quot;时，有个方向。</p><h2 id="_6-注意事项小结" tabindex="-1"><a class="header-anchor" href="#_6-注意事项小结" aria-hidden="true">#</a> 6. 注意事项小结</h2><ul><li><code>of()</code> 传参要么以 <code>&lt;svg</code> 开头（svg 文本），要么是文件路径；一个普通字符串两边都靠不上时会解析失败</li><li>默认输出 png；输出 jpg 时注意透明区域的填充问题</li><li>tiff 输出在 jdk8 及以下需要额外引入 <code>imageio-tiff</code></li><li><code>asFile()</code> 会根据后缀自动决定渲染格式，未识别的后缀会直接抛异常</li><li>渲染性能不算突出，模板场景请配合缓存使用（下一篇介绍），单次渲染的大尺寸 svg 也不建议做成高频接口</li></ul><h2 id="_7-旧版本-3-0-0-及之前-用法对比" tabindex="-1"><a class="header-anchor" href="#_7-旧版本-3-0-0-及之前-用法对比" aria-hidden="true">#</a> 7. 旧版本（3.0.0 及之前）用法对比</h2><p>如果您还在使用 3.0.0 及之前的版本，使用姿势与最新版本并不通用，这里做一个简要对比，强烈推荐升级到最新版。</p><p>旧版本对外暴露的核心方法是：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token doc-comment comment">/**
 * 将SVG转换成PNG
 *
 * <span class="token keyword">@param</span> <span class="token parameter">path</span>     可以是http开头的SVG文件路径；可以是&lt;svg开头的纯svg内容
 * <span class="token keyword">@param</span> <span class="token parameter">paramMap</span> 变更参数键值对，key为svg元素Id value为替换内容
 */</span>
<span class="token keyword">public</span> <span class="token keyword">static</span> <span class="token class-name">BufferedImage</span> <span class="token function">convertToJpegAsImg</span><span class="token punctuation">(</span><span class="token class-name">String</span> path<span class="token punctuation">,</span> <span class="token class-name">Map</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">String</span><span class="token punctuation">,</span> <span class="token class-name">Object</span><span class="token punctuation">&gt;</span></span> paramMap<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>新旧版本的主要差异：</p><table><thead><tr><th style="text-align:center;">对比项</th><th style="text-align:center;">旧版（≤3.0.0）</th><th style="text-align:center;">新版（3.0.1+）</th></tr></thead><tbody><tr><td style="text-align:center;">入口</td><td style="text-align:center;">静态方法直接传参</td><td style="text-align:center;">链式 Builder，可读性更好</td></tr><tr><td style="text-align:center;">渲染格式</td><td style="text-align:center;">只支持 png</td><td style="text-align:center;">png / jpg / tiff 三种</td></tr><tr><td style="text-align:center;">输出方式</td><td style="text-align:center;">只返回 BufferedImage</td><td style="text-align:center;">asImg / asStream / asBytes / asFile / asSvg</td></tr><tr><td style="text-align:center;">模板传参</td><td style="text-align:center;">paramMap 集中传</td><td style="text-align:center;">addParams 链式传，支持属性替换</td></tr></tbody></table><p>旧版的使用示例（新版写法见下一篇）：</p><div class="language-java line-numbers-mode" data-ext="java"><pre class="language-java"><code><span class="token class-name">Map</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token class-name">String</span><span class="token punctuation">,</span> <span class="token class-name">Object</span><span class="token punctuation">&gt;</span></span> paramMap <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token class-name">HashMap</span><span class="token generics"><span class="token punctuation">&lt;</span><span class="token punctuation">&gt;</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
paramMap<span class="token punctuation">.</span><span class="token function">put</span><span class="token punctuation">(</span><span class="token string">&quot;svg_2&quot;</span><span class="token punctuation">,</span> <span class="token string">&quot;当前金额: ￥1314.00&quot;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">BufferedImage</span> img <span class="token operator">=</span> <span class="token class-name">SvgRenderWrapper</span><span class="token punctuation">.</span><span class="token function">convertToJpegAsImg</span><span class="token punctuation">(</span><span class="token string">&quot;&lt;svg ...&gt;...&lt;/svg&gt;&quot;</span><span class="token punctuation">,</span> paramMap<span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div>`,61),v=n("h2",{id:"_8-其他",tabindex:"-1"},[n("a",{class:"header-anchor",href:"#_8-其他","aria-hidden":"true"},"#"),s(" 8. 其他")],-1),m=n("p",null,[n("strong",null,"项目地址：")],-1),q={href:"https://github.com/liuyueyi/quick-media",target:"_blank",rel:"noopener noreferrer"},h=n("li",null,[n("code",null,"QuickMedia"),s(" 目标是创建一个专注图文，音视频，二维码处理的开源项目")],-1),b=n("p",null,[n("strong",null,"系列博文")],-1),f={href:"https://blog.hhui.top/hexblog/2017/12/17/%E5%9B%BE%E7%89%87%E5%90%88%E6%88%90%E6%94%AF%E6%8C%81%E7%9A%84%E5%89%8D%E4%B8%96%E4%BB%8A%E7%94%9F/#4-svg-%E8%BD%AC-%E5%9B%BE%E7%89%87",target:"_blank",rel:"noopener noreferrer"};function y(x,_){const o=e("RouterLink"),t=e("ExternalLinkIcon");return c(),l("div",null,[g,i(" more "),k,n("p",null,[s("旧版本也内置了模板 Document 的缓存（考虑到 svg 模板通常只有部分文字或图片有差异，缓存解析后的 Document，通过深拷贝来保证每次填充参数互不影响），这一点在新版本中保留并强化了：缓存开关可配置、缓存大小可配置。关于模板渲染与缓存的细节，请看下一篇 "),a(o,{to:"/git/quick-media/svg/02.svg%E6%A8%A1%E6%9D%BF%E6%B8%B2%E6%9F%93.html"},{default:u(()=>[s("2.svg模板渲染")]),_:1}),s("。")]),v,m,n("ul",null,[n("li",null,[n("a",q,[s("https://github.com/liuyueyi/quick-media"),a(t)])]),h]),b,n("ul",null,[n("li",null,[n("a",f,[s("图片合成支持的前世今生 - 一灰灰Blog"),a(t)])])])])}const S=p(r,[["render",y],["__file","01.svg渲染输出图片.html.vue"]]);export{S as default};
